class Solution {
public:
    ListNode* removeNodes(ListNode* head) {
        std::vector<ListNode*> st;
        ListNode* curr = head;
        while (curr) {
            while (!st.empty() && st.back()->val < curr->val) st.pop_back();
            st.push_back(curr);
            curr = curr->next;
        }
        ListNode dummy(0);
        ListNode* tail = &dummy;
        for (ListNode* node : st) {
            tail->next = node;
            tail = node;
        }
        tail->next = nullptr;
        return dummy.next;
    }
};

class Solution {
    public ListNode removeNodes(ListNode head) {
        java.util.ArrayDeque<ListNode> stack = new java.util.ArrayDeque<>();
        ListNode curr = head;
        while (curr != null) {
            while (!stack.isEmpty() && stack.peek().val < curr.val) {
                stack.pop();
            }
            stack.push(curr);
            curr = curr.next;
        }
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        java.util.List<ListNode> nodes = new java.util.ArrayList<>(stack);
        java.util.Collections.reverse(nodes);
        for (ListNode node : nodes) {
            tail.next = node;
            tail = node;
        }
        tail.next = null;
        return dummy.next;
    }
}

